```st
FUNCTION_BLOCK FB
VAR_INPUT
    enqueue  : BOOL;
    dequeue  : BOOL;
    reset    : BOOL;
    capacity : DINT;
END_VAR
VAR_OUTPUT
    elementCount : DINT := 0;
    status       : WORD := 16#0000;
END_VAR
VAR_IN_OUT
    item   : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR
VAR
    head        : DINT := 1;
    tail        : DINT := 1;
    prevEnqueue : BOOL := FALSE;
    prevDequeue : BOOL := FALSE;
END_VAR

// Rising edge on reset?
IF reset THEN
    // Reset takes priority: empty the queue immediately
    elementCount := 0;
    head := 1;
    tail := 1;
    status := 16#0000;

    // Update edge history even on reset
    prevEnqueue := enqueue;
    prevDequeue := dequeue;
    RETURN;
END_IF

// Rising edge on enqueue?
IF enqueue AND NOT prevEnqueue THEN
    IF elementCount < capacity THEN
        buffer[tail] := item;

        // Advance tail with wraparound
        IF tail >= capacity THEN
            tail := 1;
        ELSE
            tail := tail + 1;
        END_IF

        elementCount := elementCount + 1;
        status := 16#0000;
    ELSE
        // Queue full
        status := 16#8002;
    END_IF
END_IF

// Rising edge on dequeue?
IF dequeue AND NOT prevDequeue THEN
    IF elementCount > 0 THEN
        // Get front element
        item := buffer[head];

        // Advance head with wraparound
        IF head >= capacity THEN
            head := 1;
        ELSE
            head := head + 1;
        END_IF

        elementCount := elementCount - 1;
        status := 16#0000;
    ELSE
        // Queue empty
        status := 16#8001;
    END_IF
END_IF

// Update previous states for next scan
prevEnqueue := enqueue;
prevDequeue := dequeue;
END_FUNCTION_BLOCK
```

